import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

type Kind = "w9" | "insurance_certificate" | "contract";

const SAMPLE_FOR_KIND: Record<Kind, string> = {
  w9: "w9.txt",
  insurance_certificate: "insurance_certificate.txt",
  contract: "contract.txt",
};

function filePart(file: string) {
  return {
    name: file,
    mimeType: "text/plain",
    buffer: fs.readFileSync(sample(file)),
  };
}

test.describe("Upload vendor documents", () => {
  test(
    "documents cannot be added to a vendor under review",
    { tag: "@DOC-06" },
    async ({ apiAs }) => {
      // Background: signed in as member, with a draft vendor
      const member = await apiAs("member");
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC-06 Locked Vendor"),
          category: "services",
          contact_email: "doc06@example.com",
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      expect(vendor.status).toBe("draft");

      // Given the vendor is in status "in_review":
      // upload the required documents, wait for processing, then submit.
      const documentIds: string[] = [];
      for (const kind of Object.keys(SAMPLE_FOR_KIND) as Kind[]) {
        const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: { kind, file: filePart(SAMPLE_FOR_KIND[kind]) },
        });
        expect(uploadResponse.status(), `upload ${kind}`).toBe(201);
        documentIds.push((await uploadResponse.json()).id);
      }

      for (const documentId of documentIds) {
        await expect
          .poll(
            async () => {
              const response = await member.get(`/api/documents/${documentId}`);
              expect(response.status()).toBe(200);
              return (await response.json()).status;
            },
            { timeout: 30_000, message: `document ${documentId} finishes processing` },
          )
          .toBe("extracted");
      }

      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);
      expect(submitResponse.status()).toBe(200);
      expect((await submitResponse.json()).status).toBe("in_review");

      // When I upload "w9.txt" as kind "w9"
      const lockedUpload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: { kind: "w9", file: filePart("w9.txt") },
      });

      // Then the response status is 409 and the error code is "vendor_locked"
      expect(lockedUpload.status()).toBe(409);
      const body = await lockedUpload.json();
      expect(body.error.code).toBe("vendor_locked");
    },
  );
});
